import {NebulaRenderer,presets} from './renderer.js?v=volume-perf-8';
import {AdaptiveNebulaQuality} from './quality.js';
const quality=new AdaptiveNebulaQuality({budgetMs:22,minScale:.35});let observedFrame=0;
const $=id=>document.getElementById(id);let settings={...presets.veil,view:'flight',travel:0},renderer,raf,last=0,time=0,dirty=true,dead=false;
const ranges=['density','scale','turbulence','dust','emission','size','stretch','layers','porosity','saturation'];
function sync(){$('compositionNote').textContent=settings.composition||'Custom composition using the selected shape and gas colours.';for(const key of [...ranges,'seed','colorA','colorB','colorC'])$(key).value=settings[key];for(const key of ranges)$(key+'Out').value=Number(settings[key]).toFixed(2);$('monochrome').checked=Boolean(settings.monochrome);$('view').value=settings.view;$('journey').value=settings.travel;$('journeyOut').value=settings.travel.toFixed(1);dirty=true;}
function read(){for(const key of ranges)settings[key]=Number($(key).value);settings.seed=Math.max(0,Math.min(999999,Number($('seed').value)||0));for(const key of ['colorA','colorB','colorC'])settings[key]=$(key).value;sync();}
function fit(){if(!renderer)return;const box=$('nebula').getBoundingClientRect();const q=$('quality').value;const base=q==='draft'?.45:q==='cinema'?Math.min(devicePixelRatio,1.25):.65;const factor=base*($('adaptive').checked&&$('motion').checked?quality.scale:1);$('nebula').width=Math.max(1,Math.round(box.width*factor));$('nebula').height=Math.max(1,Math.round(box.height*factor));settings.steps=q==='draft'?32:q==='cinema'?80:48;dirty=true;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('preset').onchange=()=>{settings={...presets[$('preset').value],view:settings.view,travel:0};time=0;sync();fit();$('sceneTitle').textContent=$('preset').selectedOptions[0].textContent.split(' /')[0];};
for(const key of [...ranges,'seed','colorA','colorB','colorC'])$(key).addEventListener('input',read);
$('randomize').onclick=()=>{settings.seed=crypto.getRandomValues(new Uint32Array(1))[0]%1000000;time=0;sync();};
$('view').onchange=()=>{settings.view=$('view').value;last=0;dirty=true;};
$('monochrome').onchange=()=>{settings.monochrome=$('monochrome').checked;dirty=true;};
$('speed').oninput=()=>{$('speedOut').value=Number($('speed').value).toFixed(1);};
$('journey').oninput=()=>{settings.travel=Number($('journey').value);$('motion').checked=false;last=0;sync();fit();};
$('resetFlight').onclick=()=>{settings.travel=0;time=0;last=0;sync();};
$('adaptive').onchange=()=>{quality.reset();fit();};$('quality').onchange=()=>{quality.reset();fit();};$('motion').checked=!matchMedia('(prefers-reduced-motion: reduce)').matches;$('motion').onchange=()=>{last=0;dirty=true;fit();};$('typography').onchange=()=>{$('typeSample').hidden=!$('typography').checked;document.querySelector('.caption').hidden=$('typography').checked;};
$('export').onclick=()=>download(new Blob([JSON.stringify({schema:'aether-nebula-v2',...settings},null,2)],{type:'application/json'}),'aether-nebula-'+settings.seed+'.json');
$('import').onclick=()=>$('recipeFile').click();$('recipeFile').onchange=async()=>{const file=$('recipeFile').files[0];if(!file)return;try{if(file.size>16384)throw Error('Recipe is too large');const data=JSON.parse(await file.text());if(!['aether-nebula-v1','aether-nebula-v2'].includes(data.schema))throw Error('Unknown recipe format');data.porosity??=.75;data.saturation??=.4;data.monochrome??=false;data.size??=2.8;data.stretch??=3;data.layers??=1.25;data.colorC??='#e7a15a';data.shape??=0;data.view??='flight';data.travel??=0;for(const key of [...ranges,'seed']){const input=$(key),value=data[key];if(!Number.isFinite(value)||value<Number(input.min)||value>Number(input.max))throw Error('Invalid '+key);}if(!Number.isInteger(data.shape)||data.shape<0||data.shape>5)throw Error('Invalid shape');if(!['study','flight'].includes(data.view)||!Number.isFinite(data.travel)||data.travel<0||data.travel>128)throw Error('Invalid camera');for(const key of ['colorA','colorB','colorC'])if(!/^#[0-9a-f]{6}$/i.test(data[key]))throw Error('Invalid colour');if(typeof data.monochrome!=='boolean')throw Error('Invalid monochrome setting');settings=Object.fromEntries([...ranges,'seed','colorA','colorB','colorC','shape','view','travel','monochrome'].map(k=>[k,data[k]]));time=0;sync();fit();$('notice').textContent='Recipe loaded.';}catch(error){$('notice').textContent=error.message;}finally{$('recipeFile').value='';}};
$('png').onclick=async()=>{if(!renderer)return;await renderer.whenIdle();if(dead)return;renderer.render(settings,time);$('nebula').toBlob(blob=>{if(blob)download(blob,'aether-nebula-'+settings.seed+'.png');else $('notice').textContent='Image export unavailable.';},'image/png');};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.preview').requestFullscreen();}catch{$('notice').textContent='Fullscreen unavailable.';}};
const observer=new ResizeObserver(fit);observer.observe($('nebula'));document.addEventListener('visibilitychange',()=>{last=0;dirty=true;});
function fail(message){$('backend').textContent='WEBGPU UNAVAILABLE';$('error').hidden=false;$('error').textContent=message;}
sync();try{renderer=new NebulaRenderer();await renderer.initialize($('nebula'));renderer.onError=message=>{dead=true;fail(message);};$('backend').textContent='● WEBGPU / VOLUME FLIGHT';fit();function frame(now){if(dead)return;const playing=$('motion').checked;if(renderer.completedFrames&&renderer.completedFrames!==observedFrame){observedFrame=renderer.completedFrames;if($('adaptive').checked&&playing&&quality.observe(renderer.frameTimeMs))fit();}if(!document.hidden&&(dirty||playing)){if(playing&&last){const dt=Math.min((now-last)/1000,.05);time+=dt;if(settings.view==='flight'){settings.travel=Math.min(128,settings.travel+dt*Number($('speed').value));$('journey').value=settings.travel;$('journeyOut').value=settings.travel.toFixed(1);if(settings.travel>=128){$('motion').checked=false;quality.reset();fit();}}}const submitted=renderer.render(settings,time);$('renderInfo').textContent=`${$('nebula').width} × ${$('nebula').height} / ${settings.steps} SAMPLES / ${Math.round(($('adaptive').checked&&playing?quality.scale:1)*100)}% RES / ${settings.view==='flight'?'JOURNEY '+settings.travel.toFixed(1):'VOLUME STUDY'}`;dirty=!submitted;}last=now;raf=requestAnimationFrame(frame);}raf=requestAnimationFrame(frame);}catch(error){renderer?.dispose();fail(error.message);}
window.addEventListener('pagehide',event=>{if(!event.persisted){dead=true;cancelAnimationFrame(raf);observer.disconnect();renderer?.dispose();}});
